const std=@import("std");
const Node=struct{left:i32,right:i32,rep:usize,mask:u64,cx:f64,cy:f64,r:f64,span:f64};
const Ctx=struct{x:[8]f64=@splat(0),y:[8]f64=@splat(0),nodes:[15]Node=undefined,used:usize=0,n:usize=0,ec:usize=0,sep:f64=0,edges:[56]f64=@splat(0)};
fn less(c:*const Ctx,a:usize,b:usize,axis:usize)bool{const a0=if(axis==0)c.x[a] else c.y[a];const b0=if(axis==0)c.x[b] else c.y[b];const a1=if(axis==0)c.y[a] else c.x[a];const b1=if(axis==0)c.y[b] else c.x[b];return a0<b0 or (a0==b0 and (a1<b1 or (a1==b1 and a<b)));}
fn build(c:*Ctx,mask:u64)usize{const at=c.used;c.used+=1;var ids:[8]usize=@splat(0);var n:usize=0;var rep:usize=8;var xmin:f64=0;var xmax:f64=0;var ymin:f64=0;var ymax:f64=0;for(0..c.n)|i|{if(mask&(1<<@intCast(i))!=0){if(n==0){xmin=c.x[i];xmax=xmin;ymin=c.y[i];ymax=ymin;}else{xmin=@min(xmin,c.x[i]);xmax=@max(xmax,c.x[i]);ymin=@min(ymin,c.y[i]);ymax=@max(ymax,c.y[i]);}ids[n]=i;n+=1;rep=@min(rep,i);}}const rx=(xmax-xmin)/2;const ry=(ymax-ymin)/2;c.nodes[at]=.{.left=-1,.right=-1,.rep=rep,.mask=mask,.cx=(xmin+xmax)/2,.cy=(ymin+ymax)/2,.r=@sqrt(rx*rx+ry*ry),.span=@max(xmax-xmin,ymax-ymin)};if(n==1)return at;const axis:usize=if(xmax-xmin>=ymax-ymin)0 else 1;var i:usize=1;while(i<n):(i+=1){const v=ids[i];var j=i;while(j>0 and less(c,v,ids[j-1],axis)):(j-=1){ids[j]=ids[j-1];}ids[j]=v;}var lm:u64=0;var rm:u64=0;for(0..n)|k|{if(k<n/2){lm|=@as(u64,1)<<@intCast(ids[k]);}else{rm|=@as(u64,1)<<@intCast(ids[k]);}}const l=build(c,lm);const r=build(c,rm);c.nodes[at].left=@intCast(l);c.nodes[at].right=@intCast(r);return at;}
fn separated(c:*const Ctx,a:usize,b:usize)bool{const u=c.nodes[a];const v=c.nodes[b];return @sqrt((u.cx-v.cx)*(u.cx-v.cx)+(u.cy-v.cy)*(u.cy-v.cy))-u.r-v.r>=c.sep*@max(u.r,v.r);}
fn crossNodes(c:*Ctx,a:usize,b:usize)void{if(separated(c,a,b)){var u=c.nodes[a].rep;var v=c.nodes[b].rep;if(u>v){const t=u;u=v;v=t;}c.edges[2*c.ec]=@floatFromInt(u);c.edges[2*c.ec+1]=@floatFromInt(v);c.ec+=1;return;}const u=c.nodes[a];const v=c.nodes[b];if(u.left<0){crossNodes(c,@intCast(v.left),a);crossNodes(c,@intCast(v.right),a);}else if(v.left<0){crossNodes(c,@intCast(u.left),b);crossNodes(c,@intCast(u.right),b);}else if(u.span>v.span){crossNodes(c,@intCast(u.left),b);crossNodes(c,@intCast(u.right),b);}else{crossNodes(c,a,@intCast(v.left));crossNodes(c,a,@intCast(v.right));}}
fn visit(c:*Ctx,at:usize)void{const n=c.nodes[at];if(n.left<0)return;const l:usize=@intCast(n.left);const r:usize=@intCast(n.right);visit(c,l);visit(c,r);crossNodes(c,l,r);}
pub export fn euclidean_t_spanner(values:?[*]const f64,length:usize,output:?[*]f64,capacity:usize)i64{const input=values orelse return -1;if(length<6 or length>18)return -1;const raw=input[0];const t=input[1];if(!std.math.isFinite(raw) or !std.math.isFinite(t) or raw<2 or raw>8 or raw!=@floor(raw) or t<1.5 or t>4)return -1;const n:usize=@intFromFloat(raw);if(length!=2+2*n)return -1;var c=Ctx{.n=n,.sep=4*(t+1)/(t-1)};for(0..n)|i|{const x=input[2+2*i];const y=input[3+2*i];if(!std.math.isFinite(x) or !std.math.isFinite(y) or @abs(x)>1000 or @abs(y)>1000 or x!=@floor(x) or y!=@floor(y))return -1;for(0..i)|j|{if(c.x[j]==x and c.y[j]==y)return -1;}c.x[i]=x;c.y[i]=y;}const root=build(&c,(@as(u64,1)<<@intCast(n))-1);visit(&c,root);const needed=1+2*c.ec;const out=output orelse return -2;if(capacity<needed)return -2;out[0]=@floatFromInt(c.ec);for(0..2*c.ec)|i|{out[i+1]=c.edges[i];}return @intCast(needed);}
